81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    /**
85	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
86	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
87	     */
88	    private static final Map<String, String> CITY_REGION = Map.of(
89	        "Sydney", "NSW",
90	        "Melbourne", "VIC",
91	        "Brisbane", "QLD");
92	
93	    /**
94	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
95	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
96	     */
97	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
98	        "NSW", new int[] {2000, 2099},
99	        "VIC", new int[] {3000, 3099},
100	        "QLD", new int[] {4000, 4099});
