150	    /**
151	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
152	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
153	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
154	     * elapsed from the birth date to the registration date (defaulting to the server's current date
155	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
156	     *
157	     * @return the age band, or {@code null} when the birth date is absent
158	     */
159	    public String getAgeBand() {
160	        if (this.birthDate == null) {
161	            return null;
162	        }
163	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
164	        int years = java.time.Period.between(this.birthDate, asAt).getYears();
165	        if (years < 18) {
166	            return "MINOR";
167	        }
168	        if (years < 65) {
169	            return "ADULT";
170	        }
171	        return "SENIOR";
172	    }
173	
174	    public String getCustomerCode() {
175	        return this.customerCode;
176	    }
177	
178	    public void setCustomerCode(String customerCode) {
179	        this.customerCode = customerCode;
180	    }
181	
182	    /**
183	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
184	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
185	     * from the owner's own customer code and registration date; {@code null} when either is absent.
186	     *
187	     * @return the membership number, or {@code null} when it cannot be derived
188	     */
189	    public String getMembershipNumber() {
190	        if (this.customerCode == null || this.registrationDate == null) {
191	            return null;
192	        }
193	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
194	    }
195	
196	    /**
197	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
198	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
199	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
200	     *
201	     * @return the Luhn check digit, or {@code null} when the customer code is absent
202	     */
203	    public Integer getCheckDigit() {
204	        if (this.customerCode == null) {
205	            return null;
206	        }
207	        int sum = 0;
208	        boolean dbl = true;
209	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
210	            char c = this.customerCode.charAt(i);
211	            if (c < '0' || c > '9') {
212	                continue;
213	            }
214	            int d = c - '0';
215	            if (dbl) {
216	                d *= 2;
217	                if (d > 9) {
218	                    d -= 9;
219	                }
220	            }
221	            sum += d;
222	            dbl = !dbl;
223	        }
224	        return (10 - (sum % 10)) % 10;
225	    }
226	
227	    /**
228	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
229	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
230	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
231	     *
232	     * @return the membership level, an integer from 1 to 3
233	     */
234	    public Integer getMembershipLevel() {
235	        int level = 1;
236	        boolean hasEmail = this.email != null && !this.email.isBlank();
237	        if (hasEmail) {
238	            level++;
239	        }
240	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
241	        if (hasNoNamesakes) {
242	            level++;
243	        }
244	        return Math.min(level, 3);
245	    }
246	
247	    /**
248	     * The owner's locality, the canonical region string. Once the owner has a
249	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
250	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
251	     * source of truth. Before the customer code is assigned (for example while a create is still
252	     * validating the postcode) it falls back to the region the code will be built from: the
253	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
254	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
255	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
256	     *
257	     * @return the canonical region string, or {@code 'UNKNOWN'}
258	     */
259	    public String getLocality() {
260	        if (this.customerCode != null) {
261	            int dash = this.customerCode.indexOf('-');
262	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
263	        }
264	        return deriveRegion();
265	    }
266	
267	    /**
268	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
269	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
270	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
271	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
272	     * the same region for known cities but disambiguates cities that share a name.
273	     *
274	     * @return the canonical region string, or {@code 'UNKNOWN'}
275	     */
276	    private String deriveRegion() {
277	        String region = regionFromPostcode();
278	        if (region != null) {
279	            return region;
280	        }
281	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
282	    }
283	
284	    /**
285	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
286	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
287	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
288	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
289	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
290	     * owner's region, telephone and last name. Call this once at create time and store the result via
291	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
292	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
293	     *
294	     * @return the assembled customer code
295	     */
296	    public String buildCustomerCode() {
297	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
298	    }
299	
300	    /**
301	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
302	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
303	     *
304	     * @param value the value to hash
305	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
306	     */
307	    private static String sha256Hex8(String value) {
308	        try {
309	            byte[] digest = MessageDigest.getInstance("SHA-256")
310	                .digest(value.getBytes(StandardCharsets.UTF_8));
311	            StringBuilder hex = new StringBuilder(8);
312	            for (int i = 0; i < 4; i++) {
313	                hex.append(String.format("%02X", digest[i]));
314	            }
315	            return hex.toString();
316	        }
317	        catch (NoSuchAlgorithmException e) {
318	            throw new IllegalStateException("SHA-256 algorithm not available", e);
319	        }
320	    }
321	
322	    /**
323	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
324	     * absent, not a 4-digit number, or in no known range.
325	     *
326	     * @return the matching region, or {@code null}
327	     */
328	    private String regionFromPostcode() {
329	        if (this.postcode == null) {
330	            return null;
331	        }
332	        int value;
333	        try {
334	            value = Integer.parseInt(this.postcode.trim());
335	        }
336	        catch (NumberFormatException ex) {
337	            return null;
338	        }
339	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
340	            int[] range = entry.getValue();
341	            if (value >= range[0] && value <= range[1]) {
342	                return entry.getKey();
343	            }
344	        }
345	        return null;
346	    }
347	
348	    /**
349	     * The owner's preferred contact channel, derived from the owner's details. Returns
350	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
351	     *
352	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
353	     */
354	    public String getContactPreference() {
355	        boolean hasEmail = this.email != null && !this.email.isBlank();
356	        return hasEmail ? "EMAIL" : "PHONE";
357	    }
358	
359	    /**
360	     * The owner's identity key, the single derived value used for duplicate detection. It is the
361	     * owner's normalized telephone, email (empty when absent) and household id joined with
362	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
363	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
364	     * are equal, so two members of the same household with different telephones differ here and are
365	     * both allowed.
366	     *
367	     * @return the derived identity key
368	     */
369	    public String getIdentityKey() {
370	        return (this.telephone == null ? "" : this.telephone) + "|"
371	            + (this.email == null ? "" : this.email) + "|"
372	            + (this.householdId == null ? "" : this.householdId);
373	    }
374	
375	    public String getHouseholdId() {
376	        return this.householdId;
377	    }
378	
379	    public void setHouseholdId(String householdId) {
380	        this.householdId = householdId;
381	    }
382	
383	    public Integer getNamesakeCount() {
384	        return this.namesakeCount;
385	    }
386	
387	    public void setNamesakeCount(Integer namesakeCount) {
388	        this.namesakeCount = namesakeCount;
389	    }
390	
391	    public Integer getHouseholdSize() {
392	        return this.householdSize;
393	    }
394	
395	    public void setHouseholdSize(Integer householdSize) {
396	        this.householdSize = householdSize;
397	    }
398	
399	    public String getPostcode() {
400	        return this.postcode;
401	    }
402	
403	    public void setPostcode(String postcode) {
404	        this.postcode = postcode;
405	    }
406	
407	    public Boolean getBulkSignupWarning() {
408	        return this.bulkSignupWarning;
409	    }
410	
411	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
412	        this.bulkSignupWarning = bulkSignupWarning;
413	    }
