415	    /**
416	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
417	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
418	     */
419	    @PrePersist
420	    void onCreate() {
421	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
422	    }
423	
424	    /**
425	     * Resolves the effective registration date and rolls it onto a business day. An absent
426	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
427	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
428	     * becomes the following Monday, while any weekday is returned unchanged.
429	     *
430	     * <p>This is the single definition of both the defaulting and the business-day roll, used
431	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
432	     * stamps the owner and by the create endpoint that counts owners per business day.
433	     *
434	     * @param supplied the registration date from the request, or {@code null} when none was supplied
435	     * @return the effective registration date, guaranteed to fall on a business day
436	     */
437	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
438	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
439	        return switch (effective.getDayOfWeek()) {
440	            case SATURDAY -> effective.plusDays(2);
441	            case SUNDAY -> effective.plusDays(1);
442	            default -> effective;
443	        };
444	    }
445	
446	    protected Set<Pet> getPetsInternal() {
447	        if (this.pets == null) {
448	            this.pets = new HashSet<>();
449	        }
450	        return this.pets;
451	    }
452	
453	    protected void setPetsInternal(Set<Pet> pets) {
454	        this.pets = pets;
455	    }
456	
457	    public List<Pet> getPets() {
458	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
459	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
460	        return Collections.unmodifiableList(sortedPets);
461	    }
462	
463	    public void setPets(List<Pet> pets) {
464	        this.pets = new HashSet<>(pets);
465	    }
466	
467	    public void addPet(Pet pet) {
468	        getPetsInternal().add(pet);
469	        pet.setOwner(this);
470	    }
471	
472	    /**
473	     * Return the Pet with the given name, or null if none found for this Owner.
474	     *
475	     * @param name to test
476	     * @return true if pet name is already in use
477	     */
478	    public Pet getPet(String name) {
479	        return getPet(name, false);
480	    }
481	
482	    /**
483	     * Return the Pet with the given name, or null if none found for this Owner.
484	     *
485	     * @param name to test
486	     * @return true if pet name is already in use
487	     */
488	    public Pet getPet(String name, boolean ignoreNew) {
489	        name = name.toLowerCase();
490	        for (Pet pet : getPetsInternal()) {
491	            if (!ignoreNew || !pet.isNew()) {
492	                String compName = pet.getName();
493	                compName = compName.toLowerCase();
494	                if (compName.equals(name)) {
495	                    return pet;
496	                }
497	            }
498	        }
499	        return null;
500	    }
501	
502	    public Pet getPet(Integer petId) {
503	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
504	    }
505	
506	    @Override
507	    public String toString() {
508	        return new ToStringCreator(this)
509	
510	            .append("id", this.getId())
511	            .append("new", this.isNew())
512	            .append("lastName", this.getLastName())
513	            .append("firstName", this.getFirstName())
514	            .append("address", this.address)
515	            .append("city", this.city)
516	            .append("telephone", this.telephone)
517	            .toString();
518	    }
519	}
